import{_ as s,o as n,c as e,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"Codegen","description":"","frontmatter":{},"headers":[],"relativePath":"compilers/codegen/index.md","filePath":"compilers/codegen/README.md","lastUpdated":1788475713000}'),t={name:"compilers/codegen/index.md"};function l(p,a,o,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="codegen" tabindex="-1">Codegen <a class="header-anchor" href="#codegen" aria-label="Permalink to &quot;Codegen&quot;">​</a></h1><p>机器无关优化在 IR 跑完之后，进入<strong>机器相关</strong>阶段。任务是把 IR 翻译成目标 CPU 指令序列——指令选择、寄存器分配、指令调度、peephole 优化、JIT 编译（如果支持）。这一阶段成果直接决定最后 30% 的性能。**LLVM 后端 <strong>SelectionDAG → MachineInstr → Machine Function Pass → MC Layer</strong> 是教科书级别的工业 stream；HotSpot C2 用 IR graph 直接 emit 寄存器分配器；Cranelift 用 CLIF 一步到位。</p><ul><li><a href="./llvm">LLVM IR / SelectionDAG / 指令选择</a></li><li><a href="./regalloc">寄存器分配：graph coloring &amp; linear scan</a></li><li><a href="./jit">JIT、Tiered Compilation、V8 Turbofast、Cranelift</a></li></ul><h2 id="后端的几个阶段" tabindex="-1">后端的几个阶段 <a class="header-anchor" href="#后端的几个阶段" aria-label="Permalink to &quot;后端的几个阶段&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IR (SSA form, machine-independent)</span></span>
<span class="line"><span>   ↓  Instruction Selection        (IR -&gt; 目标架构指令模板)</span></span>
<span class="line"><span>   ↓  Register Allocation          (虚拟寄存器 -&gt; 物理寄存器/spill)</span></span>
<span class="line"><span>   ↓  Instruction Scheduling       (指令顺序依赖图)</span></span>
<span class="line"><span>   ↓  Peephole Optimization        (局部模式替换)</span></span>
<span class="line"><span>   ↓  Machine Code Emission        (binary)</span></span></code></pre></div><h3 id="instruction-selection" tabindex="-1">Instruction Selection <a class="header-anchor" href="#instruction-selection" aria-label="Permalink to &quot;Instruction Selection&quot;">​</a></h3><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   (LLVM </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">IR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>在 ARM 上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add r0, r1, r2          (单条加法)</span></span></code></pre></div><p>在 x86 上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov rax, rbx</span></span>
<span class="line"><span>add rax, rcx            (必须先 mov，因为 add 目的端是 src-dst)</span></span></code></pre></div><p><strong>指令选择</strong> 决定用哪条机器指令实现 IR 操作。LLVM 用 SelectionDAG（树覆盖），GCC 用机器描述 macro，HotSpot C2 直接产生 ideal graph 节点。tree-covering 算法是经典 Burmese (Burs, Graham- Henry) 算法：找树最便宜的覆盖。</p><h3 id="register-allocation" tabindex="-1">Register Allocation <a class="header-anchor" href="#register-allocation" aria-label="Permalink to &quot;Register Allocation&quot;">​</a></h3><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sum </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i];</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              // 用到_sum, i, 临时寄存器</span></span></code></pre></div><p>物理寄存器只有 16-32 个（x86-64 GPR），但活跃变量可能上百。<strong>Spill</strong>——把不活跃的临时存到栈——是 register allocation 的核心难题。两个经典算法：<strong>Graph Coloring</strong>（Chaitin-Briggs, 复杂但质量最好）与 <strong>Linear Scan</strong>（Poletto-Sarkar, 简单快但稍逊）。</p><h3 id="instruction-scheduling" tabindex="-1">Instruction Scheduling <a class="header-anchor" href="#instruction-scheduling" aria-label="Permalink to &quot;Instruction Scheduling&quot;">​</a></h3><p>CPU 流水线深度：现代 x86 ~14-19 stages，ARM Cortex-A78 ~15 stages。指令间数据依赖会导致 stall——把无关指令插进依赖链中能增加 ILP (Instruction-Level Parallelism)。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov rax, [rsp]        ; load 1, latency 3-4 cyc</span></span>
<span class="line"><span>add rbx, rax          ; depends on rax</span></span>
<span class="line"><span>mov rcx, [rsp+8]      ; load 2, independent</span></span>
<span class="line"><span>add rdx, rcx          ; depends on rcx</span></span></code></pre></div><p>调度器把无关的 load 提到前面：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov rax, [rsp]</span></span>
<span class="line"><span>mov rcx, [rsp+8]</span></span>
<span class="line"><span>add rbx, rax</span></span>
<span class="line"><span>add rdx, rcx</span></span></code></pre></div><p>两个 load 并发执行。<strong>List Scheduling</strong> 算法：每 cycle 选依赖闭包里就绪的指令送入。Hardware 多发射让编译器调度放宽；现代 CPU 的 out-of-order 让 compiler scheduling 不那么关键，但仍是关键因素。但 in-order CPU (Cortex-A55、Atom) 仍极依赖 compiler scheduling。</p><hr><p>下一节 → <a href="./llvm">LLVM IR / SelectionDAG / 指令选择</a></p>`,23)])])}const u=s(t,[["render",l]]);export{g as __pageData,u as default};
